mapper.select:
SELECT id,is_admin,banned_until,phone,email,nickname,phone_country_code
FROM t_profiles
WHERE deleted_at IS NULL

  AND email=#{contact}

    AND phone=#{contact}
    AND (
      phone_country_code=#{country}
      OR (#{country}='+86' AND (phone_country_code IS NULL OR phone_country_code='' OR phone_country_code='+86'))
    )


LIMIT 1
